// ===================================================================
// build-tailwind.mjs — css/tailwind.css, from the classes the site uses
//
// The desktop used to load tailwind's play cdn: a 127kb compiler that
// blocked the parser, recompiled the same small stylesheet on every visit,
// and then watched every DOM change for new class names. The sparkles alone
// kept it busy. Its entire output fits in a file, so now it is one.
//
// Same deal as feed.json: this writes a file, the file gets committed, and
// the site still has no build step. Nothing here runs on deploy.
// check-css.mjs fails the build if the markup asks for a class this file
// does not have, which is what happens the first time someone reaches for
// a new utility and forgets this exists.
//
//   npm run css
//
// The versions are the ones the cdn was serving when this replaced it, so
// the same class means the same rule it always did. Tailwind and its plugins
// go in a temp directory rather than node_modules, because the site has no
// dependencies and this is not going to be what changes that.
// ===================================================================
import { execFileSync, execSync } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const OUT = 'css/tailwind.css';

const PACKAGES = ['tailwindcss@3.4.17', '@tailwindcss/forms@0.5.10', '@tailwindcss/container-queries@0.1.1'];

// Everything that loads this stylesheet and can put a class on the page: the
// three pages that link it, and every script they can pull in, the lazy games
// included. The standalone pages in apps/ and games/<name>/ bring their own
// styles and do not load this file, so scanning them would only add weight.
export const CONTENT = [
    'index.html', 'guestbook.html', 'links.html',
    'js/*.js',
    'games/netplay.js',
    'games/jokerz/*.js', 'games/echoes/*.js', 'games/wizardz/*.js',
    'games/troll-problem/*.js', 'games/become-user/*.js'
];

const CONFIG = `module.exports = {
    content: ${JSON.stringify(CONTENT)},
    darkMode: 'class',
    theme: {
        extend: {
            colors: {
                'primary': '#0df259',
                'background-light': '#f5f8f6',
                'background-dark': '#102216',
                'retro-gray': '#c0c0c0',
                'retro-blue': '#000080',
                'winamp-base': '#29293d',
            },
            fontFamily: {
                'header': ['Comic Sans MS', 'Comic Sans', 'cursive'],
                'body': ['Times New Roman', 'Times', 'serif'],
                'pixel': ['Courier New', 'monospace'],
            },
            borderRadius: { 'DEFAULT': '0.125rem', 'lg': '0.25rem', 'xl': '0.5rem', 'full': '0.75rem' },
            backgroundImage: {
                'stars': 'radial-gradient(white, rgba(255,255,255,.2) 2px, transparent 3px), radial-gradient(white, rgba(255,255,255,.15) 1px, transparent 2px), radial-gradient(white, rgba(255,255,255,.1) 2px, transparent 3px)',
            },
        },
    },
    plugins: [require('@tailwindcss/forms'), require('@tailwindcss/container-queries')],
};
`;

export function build() {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'mrhakan-tailwind-'));
    try {
        console.log('installing ' + PACKAGES.join(', ') + ' in a temp directory');
        fs.writeFileSync(path.join(tmp, 'package.json'), '{"private":true}');
        execSync('npm install --no-audit --no-fund --silent ' + PACKAGES.join(' '), { cwd: tmp, stdio: 'inherit' });
        fs.writeFileSync(path.join(tmp, 'tailwind.config.cjs'), CONFIG);
        fs.writeFileSync(path.join(tmp, 'in.css'), '@tailwind base;\n@tailwind components;\n@tailwind utilities;\n');
        // content globs resolve against the working directory
        execFileSync(process.execPath, [
            path.join(tmp, 'node_modules', 'tailwindcss', 'lib', 'cli.js'),
            '-c', path.join(tmp, 'tailwind.config.cjs'),
            '-i', path.join(tmp, 'in.css'),
            '-o', path.join(ROOT, OUT),
            '--minify'
        ], { cwd: ROOT, stdio: 'inherit' });
    } finally {
        fs.rmSync(tmp, { recursive: true, force: true });
    }
    const css = fs.readFileSync(path.join(ROOT, OUT), 'utf8');
    fs.writeFileSync(path.join(ROOT, OUT),
        '/* generated by .github/scripts/build-tailwind.mjs (npm run css). do not edit. */\n' + css.trimEnd() + '\n');
    console.log('wrote ' + OUT + ' — ' + Math.round(fs.statSync(path.join(ROOT, OUT)).size / 1024) + 'kb');
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) build();
